import json,pathlib
root=pathlib.Path('.')
variants=[('06-tsokol','Полуподвал','A squat complete two-story faded ochre provincial house with a rust-red hip roof. The karaoke occupies its semi-basement, with descending exterior steps and black tubular railing, a small curved burgundy canopy and a tiny orange neon microphone pictogram. Two low basement windows glow violet: a stocky middle-aged man sings into a wired microphone beside a bulky CRT television showing plain blue light, and a small mirror ball. Ordinary upper windows with net curtains. The contrast between a mundane old house and loud basement nightlife is the joke.'),('07-byvshee-kafe','Бывшее кафе','A complete single-story former Soviet neighborhood cafe, squat wide box with a flat roof and chunky pale turquoise fascia, beige square tile walls, three large framed windows and a modest central door. A cheap pink neon microphone pictogram attached to the facade, purple fluorescent tubes tracing just the entrance. Behind one window a middle-aged woman with voluminous 1990s hair sings into a wired microphone, next window shows burgundy curtains, a mirror ball and boxy CRT television with plain blue screen. A mismatched wall air conditioner. Clearly an enclosed exterior building, not a cutaway.'),('08-osobnyak','Дешёвый дворец','A complete compact two-story provincial pseudo-luxury karaoke mansion from the early 2000s. Cream stucco, two absurdly stout fake classical columns framing entrance, burgundy mansard roof, gold-painted railings, arched windows, little red carpet on the steps. A golden microphone pictogram above door, purple glow behind arched windows, visible middle-aged man in a dark tracksuit singing into a wired microphone behind glass, a tiny mirrored disco ball. Cheap aspirational glamour with simplified slightly worn plaster; funny and affectionate, not a real palace.'),('09-kirpich','Кирпич и хром','A complete compact one-story red brick karaoke nightclub from the late 1990s with a tall stepped parapet concealing a flat roof, oversized semicircular blue polycarbonate entrance canopy on shiny steel tubes, heavy black door, two circular windows and one rectangular front window. A vivid cyan neon microphone pictogram mounted directly on brick, pink light behind round windows; through the rectangular window two middle-aged men sing together into wired microphones next to a bulky plain-screen CRT TV. One external ventilation duct, small concrete steps. Charming tacky converted commercial building.'),('10-pridorozhny','Придорожный ресторан','A complete small detached roadside restaurant converted to karaoke in early 2000s, broad low ochre building with exaggerated burgundy tiled hip roof and a small octagonal corner turret with conical roof. Arched tinted windows, tiny amber bulbs along the entrance awning, pink neon microphone pictogram attached to facade. Through two windows see a middle-aged woman singing into a wired microphone and a balding man singing beside her, violet disco light, mirror ball and heavy burgundy curtains. Cheap provincial banquet glamour, small paved entrance slab, no road or surrounding scenery.')]
common='Use case: stylized-concept. Generate ONE standalone central illustration for a Machi Koro-style Russian business board-game card. A COMPLETE ENCLOSED BUILDING seen from OUTSIDE: full roof, front facade, side wall, foundation, compact integral paving slab. No cutaway, no roof removed, no interior diorama. Architecture occupies at least 85 percent of subject; singers are small glimpses behind glass. Playful three-quarter perspective, front facade facing slightly right, show front and right side. Clean chunky toy-like cartoon shapes, crisp dark outlines, restrained detail, simple cel shading, muted concrete and burgundy palette with concentrated violet/cyan/amber window light. No photorealism, no detailed gritty texture. 1990s–early 2000s post-Soviet tacky karaoke atmosphere. Recognition via wired microphones, CRT screen and neon microphone PICTOGRAM, never words. No letters, digits, words, logos, pseudo-writing, musical notation, signs or blank signboards anywhere. No card frame, title, numbers or UI. Centered whole building, generous 10 percent transparent margins, no clipping. Output native RGBA PNG on genuinely transparent background, alpha zero outside building and compact base. No white background, no checkerboard, no cast shadow or halo. '
for suffix,title,desc in variants:
 slug='karaoke-klub-'+suffix
 spec=json.loads((root/'prompts/central-illustration.json').read_text())
 spec['title']=title
 spec['content']={'subject':'Complete karaoke club building','description':desc,'desired_read':'Building-first, tacky post-Soviet karaoke 1990s–2000s','recognition_details':['Whole roof and exterior walls','Neon microphone pictogram','Small singers visible through windows'],'miniature_base':'Compact integral pavement slab','simplify':['Chunky architecture','Few readable window scenes'],'omit':['Text','Cutaway rooms'],'target_impression':title}
 spec['generation_prompt']=common+desc
 # Resolve orientation consistently with installed skill.
 def replace(v):
  if isinstance(v,dict):return {k:replace(x) for k,x in v.items()}
  if isinstance(v,list):return [replace(x) for x in v]
  if isinstance(v,str) and ('left side' in v or 'front-plus-left' in v or 'depth recede' in v):return 'Front facade faces slightly right; show front and right side in readable three-quarter view.'
  return v
 spec=replace(spec)
 spec['generation_prompt']=common+desc
 p=root/'prompts/central-illustrations'/f'{slug}.json';p.write_text(json.dumps(spec,ensure_ascii=False,indent=2)+'\n')
 cmd=(root/'card-commands/karaoke-klub.sh').read_text().replace('buildings/karaoke-klub.png',f'buildings/{slug}.png').replace('cards/karaoke-klub.png',f'cards/{slug}.png')
 (root/'card-commands'/f'{slug}.sh').write_text(cmd)
print([ 'karaoke-klub-'+v[0] for v in variants])
